 static void NativeHudSkin(){if(NativeSkin||InGameUI.I==null)return;var items=Resources.FindObjectsOfTypeAll(Il2CppType.Of<HUDUpgradeItem>());if(items.Length>0)EquipmentBacking=items[0].Cast<HUDUpgradeItem>().SprBackingNormal;
  // Reuse a bordered native UI sprite; a nine-slice keeps its pixel ornaments intact.
  var images=Resources.FindObjectsOfTypeAll(Il2CppType.Of<Image>());Sprite frame=null;for(int i=0;i<images.Length;i++){var candidate=images[i].Cast<Image>();var sprite=candidate.sprite;if(sprite==null||sprite.border==Vector4.zero||sprite.rect.width<120||sprite.rect.height<50)continue;string name=sprite.name.ToLowerInvariant();if(name.Contains("frame")||name.Contains("panel")||name.Contains("backing")){frame=sprite;break;}}
  for(int slot=0;slot<2;slot++){if(frame!=null){Frames[slot].sprite=frame;Frames[slot].type=Image.Type.Sliced;Frames[slot].fillCenter=false;Frames[slot].enabled=true;}for(int i=0;i<16;i++)if(EquipmentBacking!=null){var rim=SkillIcons[slot,i].transform.parent.Find("SlotRim").GetComponent(Il2CppType.Of<Image>()).Cast<Image>();rim.sprite=EquipmentBacking;rim.color=Color.white;rim.type=EquipmentBacking.border!=Vector4.zero?Image.Type.Sliced:Image.Type.Simple;}}
  NativeSkin=true;UnityEngine.Debug.Log("Coop HUD skin: frame="+(frame==null?"bronze fallback":frame.name)+", equipment="+(EquipmentBacking==null?"bronze fallback":EquipmentBacking.name));
 }
 static void Skill(int slot,int index,UpgradeInfo info,int level){if(index>=16)return;var image=SkillIcons[slot,index];image.transform.parent.gameObject.SetActive(true);info.ApplyIcon(image);image.enabled=image.sprite!=null;SkillLevels[slot,index].text=Math.Max(1,level).ToString();}
 static void UpdateHud(){NativeHudSkin();ExperienceLabel.text=CoopLocalization.Text("Nível ")+BattleSaveData.I.UpgradeLvl+"  •  XP "+BattleSaveData.I.CurXP.ToString("0");
  for(int slot=0;slot<2;slot++){var character=CoopCharacters.CharacterFor(slot);if(character==null)return;Portraits[slot].sprite=character.GetInfo().GetIconSprite();Texts[slot].text=CoopLocalization.Text("J")+(slot+1)+"  •  "+character.GetInfo().Name;HealthLabels[slot].text=CoopVitals.Life.Health[slot].ToString("0.#")+" / "+CoopVitals.Life.Maximum[slot].ToString("0.#");float fraction=Mathf.Clamp01(CoopVitals.Life.Health[slot]/Mathf.Max(1,CoopVitals.Life.Maximum[slot]));Bars[slot].rectTransform.anchorMax=new Vector2(0.218f+0.724f*fraction,0.74f);Bars[slot].color=fraction<=0.25f?new Color(1,0.24f,0.22f):PlayerColor(slot);
   string status=CoopVitals.Life.Down(slot)?(CoopVitals.Life.Rescued[slot]?CoopLocalization.Text("FORA DA PARTIDA"):CoopLocalization.Text("RESGATE AUTOMÁTICO")):(CoopLocalization.Text("Resgate ")+(CoopVitals.Life.Rescued[slot]?"0/1":"1/1")+"  •  AUTO "+(TwoGamepads.Automatic(slot)?"ON":"OFF"));StatusLabels[slot].text=status;Hints[slot].text=CoopBossMechanics.Warning;
   int count=0;var heroes=CoopCharacters.HeroesFor(slot);if(heroes!=null)for(int i=0;i<heroes.Count&&count<16;i++)Skill(slot,count++,heroes[i].GetInfo(),heroes[i].Lvl);var passives=CoopCharacters.PassivesFor(slot);if(passives!=null)for(int i=0;i<passives.Count&&count<16;i++)Skill(slot,count++,passives[i].GetInfo(),passives[i].Lvl);for(int i=count;i<16;i++)SkillIcons[slot,i].transform.parent.gameObject.SetActive(false);
  }
