 public static void ResetRound(){ResultShown=ResultAck=false;ResultAt=0;Gate.Reset();}
 public static void ResultReady(){ResultAt=Time.unscaledTime+0.8f;}
 public static Report Capture(bool victory,int phase,int first,int second){return new Report{Victory=victory,Phase=phase,Characters=new[]{first,second},Damage=(long[])CoopRoundStats.Damage.Clone(),Kills=(int[])CoopRoundStats.Kills.Clone(),Experience=(int[])CoopRoundStats.Experience.Clone(),Points=(int[])CoopRoundStats.Points.Clone(),Proofs=(int[])CoopRoundStats.Proofs.Clone(),Rescued=(bool[])CoopVitals.Life.Rescued.Clone(),TeamDamage=CoopRoundStats.TeamDamage,TeamKills=CoopRoundStats.TeamKills,NativeKills=BattleSaveData.I.NumKills};}
 static void ShowResult(){if(ResultShown||ResultAck||CoopMode.State.LastResult==null)return;ResultShown=true;Gate.Reset();NativeChoiceOverlay.ClearChoices();Time.timeScale=0;}
 public static bool InterceptReturn(){if(!CoopRoundStats.Complete||ResultAck)return false;ShowResult();return true;}
 public static void AcknowledgeForTest(){if(!CoopTestHarness.Active)return;ResultAck=true;ResultShown=false;NativeChoiceOverlay.Hide();Time.timeScale=1;}
 public static void OpenChallenges(){Challenges=true;CoopCharacters.Selecting=false;ChallengeIndex[0]=ChallengeIndex[1]=0;NextInput[0]=NextInput[1]=0;NativeChoiceOverlay.ClearChoices();}
 static void CloseChallenges(){Challenges=false;CoopCharacters.Selecting=true;NativeChoiceOverlay.Hide();}
 static List<string> ChallengeList(int slot){var lines=new List<string>();var chars=new List<CharInfo>();foreach(var meta in MetaSaveData.I.Chars)if(meta.GetInfo().IncludeInGame())chars.Add(meta.GetInfo());chars.Sort((a,b)=>((int)a.Type).CompareTo((int)b.Type));foreach(var info in chars)lines.Add(info.Name+"\n"+(CoopMode.Unlocked(info.Type)?CoopLocalization.Text("LIBERADO"):CoopMode.CharacterRequirement(info.Type)));
  var phases=CoopMode.Phases;for(int i=0;i<phases.Count;i++)lines.Add(CoopLocalization.Text("Fase ")+(i+1)+"\n"+CoopLocalization.StageName(phases[i])+"\n"+(i==0||CoopMode.State.Cleared.Contains((int)phases[i-1].Type)?CoopLocalization.Text("LIBERADA"):CoopLocalization.Text("Vencer a fase anterior")));
  string[] names={CoopLocalization.Text("Resistência"),CoopLocalization.Text("Força"),CoopLocalization.Text("Liderança"),CoopLocalization.Text("Velocidade"),CoopLocalization.Text("Destreza"),CoopLocalization.Text("Inteligência")};for(int stat=0;stat<6;stat++){int rank=CoopMode.State.Players[slot].Stats[stat];lines.Add(names[stat]+" +"+rank+"\n"+(rank>=10?CoopLocalization.Text("MÁXIMO"):CoopLocalization.Text("Próximo: ")+CoopProgressRules.UpgradePrice(rank)+CoopLocalization.Text(" pontos\nVencer fase ")+(CoopProgressRules.RequiredUpgradeStage(rank,phases.Count)+1)));}return lines;}
 public static void Tick(){
  CreateHud();bool battle=CoopVitals.Active&&CoopCharacters.IndependentReady&&CoopCharacters.CharacterFor(0)!=null&&CoopCharacters.CharacterFor(1)!=null&&!ResultShown;NativeHudVisibility(CoopMode.Enabled&&SceneMgr.GetCurScene()==GameScene.kGame);if(Hud!=null)Hud.SetActive(battle);if(battle&&Time.unscaledTime>=NextHud){NextHud=Time.unscaledTime+0.1f;UpdateHud();}
  if(CoopRoundStats.Complete&&!ResultAck&&GameMgr.I!=null&&Time.unscaledTime>=ResultAt)ShowResult();
  if(CoopTestHarness.Active||!Application.isFocused)return;
  if(ResultShown){for(int slot=0;slot<2;slot++){var pad=TwoGamepads.GetPad(slot);if(pad==null){if(TwoGamepads.GetPad(1-slot)!=null)Gate.Confirm(slot,true);else Gate.Cancel(slot);continue;}if(pad.a.justPressed)Gate.Confirm(slot,true);if(pad.b.justPressed)Gate.Cancel(slot);}if(Gate.Complete){ResultAck=true;ResultShown=false;Time.timeScale=1;NativeChoiceOverlay.Hide();GameMgr.I.GoToBase();}return;}
  if(Challenges){for(int slot=0;slot<2;slot++){var pad=TwoGamepads.GetPad(slot);if(pad==null)continue;if(pad.b.justPressed){CloseChallenges();return;}float x=pad.leftStick.horizontal.value;if(Mathf.Abs(x)<0.4f)NextInput[slot]=0;if(Mathf.Abs(x)>0.55f&&Time.unscaledTime>=NextInput[slot]){int count=ChallengeList(slot).Count;ChallengeIndex[slot]=(ChallengeIndex[slot]+(x>0?1:-1)+count)%count;NextInput[slot]=Time.unscaledTime+0.2f;}}}
 }
 public static void Draw(){if(ResultShown){var r=CoopMode.State.LastResult;NativeChoiceOverlay.Show(r.Victory?CoopLocalization.Text("Vitória da dupla"):CoopLocalization.Text("Fim da partida"),CoopLocalization.Text("A / X: pronto • Os dois confirmam para voltar aos menus. Dano compartilhado: ")+r.TeamDamage+CoopLocalization.Text(" • Eliminações compartilhadas: ")+r.TeamKills);for(int slot=0;slot<2;slot++)NativeChoiceOverlay.Details(slot,CoopLocalization.Text("Dano causado: ")+r.Damage[slot]+CoopLocalization.Text("\nInimigos derrotados: ")+r.Kills[slot]+CoopLocalization.Text("\nXP recebido: ")+r.Experience[slot]+CoopLocalization.Text("\nPontos: ")+r.Points[slot]+CoopLocalization.Text("\nProvas conquistadas: ")+r.Proofs[slot]+CoopLocalization.Text("\nResgate utilizado: ")+(r.Rescued[slot]?CoopLocalization.Text("Sim"):CoopLocalization.Text("Não")),Gate.Ready[slot]);}
  else if(Challenges){NativeChoiceOverlay.Show(CoopLocalization.Text("Desafios e desbloqueios"),CoopLocalization.Text("Personagens e fases são compartilhados • Cada painel inclui suas melhorias • Analógico: navegar • B: voltar"));for(int slot=0;slot<2;slot++){var list=ChallengeList(slot);NativeChoiceOverlay.Card(slot,"",false,null);NativeChoiceOverlay.Options(slot,list.ToArray(),new Sprite[list.Count],ChallengeIndex[slot]);}}
 }
